import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as o,o as n,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const v=JSON.parse('{"title":"Arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/architecture.md","filePath":"es-ES/dev-guide/architecture.md","lastUpdated":1787473456000}'),d={name:"es-ES/dev-guide/architecture.md"};function c(s,e,l,t,u,p){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h1><p><img src="'+a+'" alt="Lertaro architecture"></p><h2 id="division-en-procesos" tabindex="-1">División en procesos <a class="header-anchor" href="#division-en-procesos" aria-label="Permalink to &quot;División en procesos&quot;">​</a></h2><p>Lertaro se ejecuta como tres procesos independientes, deliberadamente aislados por nivel de privilegio y ciclo de vida:</p><ul><li><strong><code>Lertaro.Service</code></strong> — un servicio de Windows que se ejecuta como <code>LocalSystem</code>. Es responsable de toda la indexación de archivos: lee el USN Journal y la MFT de las unidades NTFS/ReFS, recorre y vigila directamente otros sistemas de archivos locales (que no tienen journal que leer), escanea y almacena en caché los recursos compartidos de red, y responde a las consultas de búsqueda a través de una named pipe. Ejecutar esto a nivel SYSTEM permite leer los metadatos de volumen sin procesar que cualquier cuenta de usuario tiene permiso de ver, sin conceder al proceso interactivo de la App privilegios elevados que no necesita.</li><li><strong><code>Lertaro.App</code></strong> — la aplicación WPF de sesión, por usuario: las ventanas de búsqueda, la ventana de Configuración, la gestión de atajos y la interfaz de Acciones/QuickLook. Se comunica con el Servicio mediante una named pipe (<code>SearchService</code>/<code>UsnServicePipeServer</code> en <code>Core.Services</code>) y nunca accede directamente al índice en disco. También aloja una segunda pipe propia, por usuario (<code>AppSearchPipeService</code>), que permite a la utilidad de línea de comandos <code>lff</code> (ver <a href="./../user-guide/cli.html">Búsqueda por línea de comandos</a>) reutilizar el estado de búsqueda ya inicializado de la App — proveedores de alias/plugins cargados, índices de unidades de red configurados — en lugar de que un proceso cliente independiente tenga que replicar esa configuración por sí mismo.</li><li><strong><code>Lertaro.Service --hook</code></strong> — un pequeño proceso independiente que aloja el hook de teclado global de bajo nivel, de modo que un fallo del hook o una aplicación en primer plano mal comportada no puedan hacer caer con ellos al proceso principal de la App. También carga los adaptadores de integración de ventana de los plugins y ejecuta sus llamadas él mismo — ver <a href="#donde-encajan-los-plugins">Dónde encajan los plugins</a> más abajo.</li></ul><h2 id="nucleo-compartido" tabindex="-1">Núcleo compartido <a class="header-anchor" href="#nucleo-compartido" aria-label="Permalink to &quot;Núcleo compartido&quot;">​</a></h2><p><code>Core</code> es una biblioteca de clases referenciada tanto por el Servicio como por la App. Contiene:</p><ul><li>El motor de búsqueda (<code>Core/SearchIndex/Fzf/*</code>) — una implementación de coincidencia difusa basada en el algoritmo de la herramienta de línea de comandos <code>fzf</code>, más un analizador de consultas (<code>SearchQueryParser</code>) para segmentar por letra de unidad y para el modo de búsqueda por ruta.</li><li>El índice en tiempo de ejecución (<code>Core/IndexV2/*</code>) — un formato de instantánea columnar mapeado en memoria, construido a partir de las lecturas de USN/MFT, con una capa delta en memoria para los cambios posteriores a la última instantánea.</li><li>Contratos de IPC (<code>SearchRequestMessage</code>, <code>SearchResponseBinarySerializer</code>, ...) compartidos literalmente por ambos procesos, de modo que la App y el Servicio siempre coinciden en el formato de la comunicación.</li><li><code>Logger</code> — escribe en archivos de registro por proceso (<code>service.log</code>, <code>app.log</code>, <code>hook.log</code>), todos legibles (aunque no todos editables) desde el visor de registros de la App en Configuración → Estado del Servicio.</li></ul><h2 id="donde-encajan-los-plugins" tabindex="-1">Dónde encajan los plugins <a class="header-anchor" href="#donde-encajan-los-plugins" aria-label="Permalink to &quot;Dónde encajan los plugins&quot;">​</a></h2><p>Los plugins son ensamblados <code>.dll</code> que referencian <code>PluginSdk</code> y son cargados por el proceso de la App (ver <a href="./getting-started.html">Primeros pasos</a> y <a href="./packaging.html">Empaquetado y despliegue</a>). Lertaro incluye plugins integrados como ejemplos de referencia — <code>Lertaro.Plugins.CoreExtensions</code> (acciones de archivo integradas y la integración con el menú contextual del shell), <code>Lertaro.Plugins.PinyinAlias</code> (alias en pinyin para nombres de archivo en chino) y <code>Lertaro.Plugins.FlowLauncherBridge</code> (que conecta plugins de Flow Launcher de terceros en formatos C#, Python 3.12, Node.js v20 LTS y ejecutables con entornos aislados) — ver <a href="./examples.html">Plugins de ejemplo</a> para un recorrido por los plugins nativos.</p><p>Los plugins nunca se comunican directamente con el Servicio; interactúan con la App a través de las interfaces documentadas en la Referencia del SDK de Plugins, y con el índice en disco (cuando necesitan directorios indexados personalizados) a través de <code>DirectoryIndexerService</code>, que actúa de intermediario con el Servicio en su nombre.</p><p>Los adaptadores de integración de ventana son la única excepción a ser exclusivos de la App: las implementaciones de <a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code> e <code>IInlineSearchAdapter</code></a> se cargan una segunda vez en el proceso Hook, y sus llamadas se ejecutan ahí en lugar de en la App. Esto es lo que permite que Lertaro controle una ventana elevada del Explorador de archivos, un diálogo de archivos o un gestor de archivos de terceros, aunque la propia App siempre se ejecute sin elevación — Windows impide que un proceso con menos privilegios envíe entradas a uno con más privilegios, por lo que la llamada debe originarse en un proceso que se ejecute con el mismo nivel de privilegio que la ventana de destino.</p>',12)])])}const h=o(d,[["render",c]]);export{v as __pageData,h as default};
